        '{"proctoring":false,"require_screen_share":false,"randomize_questions":false,"randomize_options":false,"pass_mark_percent":50,"results_published":false,"access_mode":"shared_link","identity_fields":[],"eligible_class_ids":["0a400000-0000-4000-8000-000000000109"],"attempt_policy":"single_resume","attempt_mode":"limited","max_attempts":1,"calculator":true,"criterion_reporting":true,"sections":[{"id":"A","title":"Part A — Objective questions","questions":25,"marks":30,"instructions":"25 questions · 30 marks. Level 1 (Q1–9) circle the correct letter; True or False (Q10–14) circle T or F; Matching (Q15–18) write one letter, P to U, in each box; Level 2 short response (Q19–20) write the answer in the box; Level 3 challenge (Q21–25) circle the correct letter."},{"id":"B","title":"Part B — Theory questions","questions":20,"marks":70,"instructions":"20 questions · 70 marks. Write all working, tables, diagrams and reasoning in your separate exam script. Task 1 = Criterion A (22), Task 2 = Criterion B (15), Task 3 = Criterion C (18), Task 4 = Criterion D (15)."}],"criterion_totals":{"A":32,"B":20,"C":24,"D":24},"source":"myp4-term1-summative-first-term-2026-version-d","formula_sheet":{"version":1,"title":"Formulas for this paper","groups":[{"title":"Averages","items":[{"latex":"\\bar{x} = \\dfrac{\\Sigma x}{n}","note":"Mean of n individual values."},{"latex":"\\bar{x} = \\dfrac{\\Sigma fx}{\\Sigma f}","note":"Estimated mean of a frequency table; x is a value or class midpoint."},{"latex":"\\text{range} = \\text{largest} - \\text{smallest}","note":"A simple measure of spread."}]},{"title":"Grouped data","items":[{"latex":"\\text{midpoint} = \\dfrac{L+U}{2}","note":"L and U are the class boundaries (not the printed limits when the data are continuous)."},{"latex":"\\text{class width} = U - L","note":"The width between the lower and upper class boundaries."},{"latex":"\\text{frequency density} = \\dfrac{\\text{frequency}}{\\text{class width}}","note":"Used for a histogram with unequal class widths."}]},{"title":"Median, quartiles and spread","items":[{"latex":"\\text{median position} = \\dfrac{n+1}{2}","note":"Position in the ordered list."},{"latex":"IQR = Q_3 - Q_1","note":"The interquartile range covers the middle 50 %."},{"latex":"\\text{lower fence} = Q_1 - 1.5\\,IQR","note":"A value below this fence is an outlier."},{"latex":"\\text{upper fence} = Q_3 + 1.5\\,IQR","note":"A value above this fence is an outlier."},{"latex":"\\sigma^2 = \\dfrac{\\Sigma (x-\\mu)^2}{N}","note":"Population variance."},{"latex":"\\sigma = \\sqrt{\\dfrac{\\Sigma (x-\\mu)^2}{N}}","note":"Population standard deviation; μ is the population mean."}]},{"title":"Cumulative frequency and coding","items":[{"latex":"\\text{median} = \\text{value at cumulative frequency } \\dfrac{N}{2}","note":"Read from a cumulative frequency curve or table."},{"latex":"Q_1 \\text{ at } \\dfrac{N}{4}, \\quad Q_3 \\text{ at } \\dfrac{3N}{4}","note":"Quartile positions on the cumulative axis."},{"latex":"y = ax + b","note":"A linear coding of every data value."},{"latex":"\\bar{y} = a\\bar{x} + b","note":"The mean follows the same coding."},{"latex":"\\sigma_y = |a|\\,\\sigma_x","note":"Adding b does not change the spread; multiplying by a scales it by |a|."}]}],"exam_id":"cf000000-0000-4000-8000-000000000002"}}'::jsonb, '3c3ed712-f409-4aa1-a645-816418e22ec4', '0a400000-0000-4000-8000-000000000109')
